# ORIGINAL: AUTOLOAD1 A4 (audit D-0387 item 3) — the `autoload` flag setter (pl-prologflag.c setAutoload :928-945, propagateAutoload :987-1000,
# set_prolog_flag_ptr :1681, set_flag_value for push_prolog_flag :1897) and `PL_set_prolog_flag` (pl-fli.c:5552), against swipl 10.1.19; the rows
# are generated by evidence/AUTOLOAD1/gen_af_rows.py.
# test/core_lang/test_autoload_flag_swipl.jl — the five values of `autoload` (false clears the mask bit PLFLAG_AUTOLOAD; explicit, true, user,
# user_or_explicit set it), the domain and type errors of the setter, a bad value that leaves the flag as it was, a module-qualified key,
# push_prolog_flag/pop_prolog_flag (they reach set_flag_value, which no longer refuses the flag), create_prolog_flag/3 (set_prolog_flag_ptr), and
# the white-box rows the kernel alone can state.
#   * A PROGRAM consulted by the kernel's loader, and cases `t_<id>(R)` run IN ORDER in one database, each wrapped in
#     `catch(Goal, error(E, _), R = raised(E))`; a case that changes `autoload` sets it back to `true`.
#   * Every answer line is swipl's, PINNED (swipl 10.1.19-1-gcbf4e189, evidence/AUTOLOAD1/gen_af_rows.py, two runs byte-identical); with
#     `swipl` on PATH the live answers are compared with the pins too.
#   * The rows run on the BOOTED database (`PL_global_data{T}()`, `bootsession` off), as swipl runs them: `set_prolog_flag(autoload, V)` calls
#     `$autoload:set_autoload/1` (boot/autoload.pl:945-956) for real, so the row of an unbound value (af08) binds it to the current one, as swipl does.
#     The LK-ONLY testsets at the end state what the kernel alone can state: the mask bit after each value, `PL_set_prolog_flag`, the
#     propagation skipped in the boot session (an unbound value is an instantiation_error, upstream's `!GD->bootsession`, pl-prologflag.c:990),
#     and the Q3 error for an undefined predicate in the boot session.
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the flag write side (src/os/pl-prologflag.jl), built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _AF = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_afs(x) = lk_sym(_AF, Symbol(x))

_af_codes(s::String) = "[" * join(Int.(collect(s)), ",") * "]"
"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms and functors by their codes."
function _af_enc(t::_AF, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "nil" : "a" * _af_codes(sym_text(t))
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s" * _af_codes(String(v))
        v isa Integer && return "i$v"
        v isa Rational && return "q$(numerator(v))r$(denominator(v))"
        v isa AbstractFloat && return "f$(v)"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "c[]" : "c" * _af_codes(sym_text(h))) * "/$(nchildren(t) - 1)(" *
           join([_af_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the driver of test_at_body_swipl.jl (consult, then every answer of each t_<id>/1, `enc`oded)
const _AF_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write(nil).
enc(T, S, S) :- atom(T), !, atom_codes(T, Cs), format("a~w", [Cs]).
enc(T, S, S) :- string(T), !, string_codes(T, Cs), format("s~w", [Cs]).
enc(T, S, S) :- integer(T), !, format("i~w", [T]).
enc(T, S, S) :- rational(T, N, D), !, format("q~wr~w", [N, D]).
enc(T, S, S) :- float(T), !, format("f~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    ( N == [] -> write('c[]') ; atom_codes(N, Cs), format("c~w", [Cs]) ),
    format("/~w(", [A]), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _af_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _AF_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(pipeline(`swipl -q $f`; stdin=devnull, stderr=devnull), String)
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end


